let current={phase:'idle',done:0,total:0};
let operation=null;
const supported='serviceWorker' in navigator&&window.isSecureContext;
function update(patch){current={...current,...patch};paintOffline();}
export function paintOffline(){const button=document.querySelector('[data-action="offline"]');if(!button)return;button.disabled=current.phase==='saving'||current.phase==='checking';button.dataset.status=current.phase;button.textContent=current.phase==='ready'?'✓ オフライン利用可':current.phase==='saving'?`保存中 ${current.done} / ${current.total||'…'}`:current.phase==='checking'?'保存を確認中…':current.phase==='error'?'保存をやり直す':current.phase==='unsupported'?'オフライン準備の案内':'オフライン準備';button.title=current.phase==='ready'?'全80枚のイラスト・年表・暗記・テストをこの端末に保存済み':'オンラインで一度、教材と全80枚のイラストをこの端末へ保存します';}
function inspect(worker){return new Promise((resolve,reject)=>{const channel=new MessageChannel();const timeout=setTimeout(()=>{channel.port1.close();reject(new Error('保存状態を確認できませんでした。オンラインでやり直してください。'));},10000);channel.port1.onmessage=event=>{clearTimeout(timeout);channel.port1.close();resolve(event.data);};worker.postMessage({type:'offline-status'},[channel.port2]);});}
function activated(worker){return new Promise((resolve,reject)=>{const check=()=>{if(worker.state==='activated'){worker.removeEventListener('statechange',check);resolve(worker);}else if(worker.state==='redundant'){worker.removeEventListener('statechange',check);reject(new Error('保存できませんでした。通信と端末の空き容量を確認して、もう一度お試しください。'));}};worker.addEventListener('statechange',check);check();});}
export async function prepareOffline(){
 if(!supported){update({phase:'unsupported'});throw new Error('この画面では保存できません。教材の公開URLをChrome・Edge・Safariで直接開いてください。');}
 if(current.phase==='ready')return true;
 if(operation)return operation;
 operation=(async()=>{update({phase:'saving',done:0,total:0});try{const registration=await navigator.serviceWorker.register('./sw.js',{scope:'./',updateViaCache:'none'});const worker=registration.installing||registration.waiting||registration.active;if(!worker)throw new Error('教材の保存を開始できませんでした。');await activated(worker);const result=await inspect(registration.active||worker);if(!result.ready)throw new Error('全教材の保存が完了していません。オンラインでやり直してください。');if(navigator.storage?.persist)navigator.storage.persist().catch(()=>{});update({...result,phase:'ready'});return true;}catch(error){console.warn('Offline preparation:',error.message);update({phase:'error'});throw error;}finally{operation=null;}})();return operation;
}
if(supported){navigator.serviceWorker.addEventListener('message',event=>{const m=event.data;if(m?.type==='offline-progress')update({phase:'saving',done:m.done,total:m.total});if(m?.type==='offline-status'&&m.ready)update({...m,phase:'ready'});if(m?.type==='offline-error'){console.warn('Offline download:',m.message);update({phase:'error'});}});navigator.serviceWorker.getRegistration('./').then(async registration=>{if(!registration?.active)return;update({phase:'checking'});try{const result=await inspect(registration.active);update({...result,phase:result.ready?'ready':'idle'});}catch{update({phase:'idle'});}}).catch(()=>{});}
